#!/usr/bin/env bash
set -euo pipefail

readonly SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
readonly DOTFILES=("bashrc" "vimrc" "gitconfig" "tmux.conf")

usage() { echo "Usage: $0 {link|unlink|status}"; }

link() {
    for dot in "${DOTFILES[@]}"; do
        local src="$SCRIPT_DIR/$dot"
        local dst="$HOME/.$dot"
        [[ -f "$src" ]] || continue
        if [[ -e "$dst" && ! -L "$dst" ]]; then
            mv "$dst" "$dst.backup.$(date +%s)"
            echo "Backed up existing .$dot"
        fi
        ln -sf "$src" "$dst"
        echo "Linked .$dot"
    done
}

unlink() {
    for dot in "${DOTFILES[@]}"; do
        local dst="$HOME/.$dot"
        [[ -L "$dst" ]] && { rm "$dst"; echo "Unlinked .$dot"; }
    done
}

status() {
    for dot in "${DOTFILES[@]}"; do
        local dst="$HOME/.$dot"
        if [[ -L "$dst" ]]; then
            echo " ✓ .$dot → $(readlink "$dst")"
        elif [[ -e "$dst" ]]; then
            echo " ! .$dot exists (not a symlink)"
        else
            echo " ✗ .$dot missing"
        fi
    done
}

case "${1:-}" in
    link) link ;;
    unlink) unlink ;;
    status) status ;;
    *) usage; exit 1 ;;
esac
